/* Original illustrative figures plus a separately labelled saved assistant pilot. No model calls. */
(()=>{
 const figures=[
 {n:'01',short:'Extraction',title:'How much survives—and how faithfully?',path:'extraction-preview/extraction-map',data:'extraction-preview/illustrative-data.csv',question:'Do extracted claims preserve what experts actually said?',read:'Right means more source claims survive; up means fewer extractions change or invent meaning. The contours reveal concentrations and failure groups across hypothetical consultations.',experiment:'Collect diverse consultations, independently annotate their focal claims, and score extracted claims against the paragraphs. Preserve failed and empty outputs, and report uncertainty across independent cases.',limit:'320 simulated points. This is the original illustrative map, preserved unchanged. The actual 24-panel assistant pilot remains a separate result.',alt:'Illustrative extraction coverage versus faithfulness with purple density contours and marginal distributions.'},
 {n:'01b',short:'Extraction · pilot',measured:true,title:'Faithfulness does not guarantee coverage',path:'assistant-extraction/assistant-extraction',data:'assistant-extraction/scores.csv',question:'How much original meaning survives in the saved assistant extraction pilot?',read:'The purple map preserves all 24 panel scores; numerals count coincident panels. On the right, four purple points pool results by scenario. Amber extensions add partially preserved claims; omissions are labelled separately. Extensions are not confidence intervals. Axes are cropped and explicitly labelled.',experiment:'The assistant extracted claims from 48 saved synthetic responses, paired into 24 panels across four scenarios, under an eight-claim limit. The same assistant reviewed preservation with reference IDs visible. These are saved outputs and provisional judgments, not an independently validated platform-model benchmark.',limit:'Saved assistant pilot: 182 of 220 focal-claim occurrences fully preserved, 10 partial and 28 omitted. The eight-claim cap accounts for all omissions. Four scenarios are not 24 independent studies; grouping loss was not isolated. No new OpenRouter calls. The original illustrative extraction map remains unchanged in the adjacent tab.',alt:'Saved assistant extraction pilot: purple coverage–faithfulness map beside four pooled scenario points, amber partial-preservation extensions and separately labelled omissions.'},
 {n:'01c',short:'Extraction · overview',composition:true,title:'From round-one responses to round-two claims',path:'paper-concepts/extraction-overview',data:'paper-concepts/grouping-design-pairs.csv',question:'Does grouping different people’s contributions preserve their original meaning? Compare the same simulated consultations before grouping (above) and after grouping (below).',read:'Panel a separates before grouping (purple, top) from after grouping (orange, bottom). Both square maps show the same 320 simulated consultations on identical axes, with common density normalisation and smoothing. Right means more coverage; up means greater faithfulness. Each map has its own 50% and 90% density contours and marginal curves. In panel b, the purple endpoint and percentage show fully preserved claims; the amber extension adds partially preserved claims, and the pale remainder shows omissions. Panel c restores coloured distributions and faint dots for individual simulated cases; larger dots mark medians and short lines the middle 50%, not confidence intervals.',experiment:'For the real experiment, save ungrouped extractions and final grouped claims from each consultation. Hold the extracted input fixed and independently judge both stages against the same source reference. Equivalent merging receives full credit; losing a consequential condition, opposing stance or attribution does not. The stacked maps currently illustrate this design: no grouping experiment has been run.',limit:'Panel a contains 320 explicitly simulated pairs. After-grouping coordinates are deliberately constructed to illustrate unchanged meaning, possible losses, and removal of unsupported content; they are not measured effects or predictions. Panel b uses saved assistant outputs and unblinded self-review; the eight-claim cap accounts for all pilot omissions. Panel c uses a separate 120 simulated cases per information type, not matched observations or measured category results. No new models or participants were run. The original standalone extraction map is unchanged.',alt:'Composed figure: two aligned square density maps, purple before grouping above and orange after grouping below; saved-pilot retention lines upper right; coloured illustrative information-type distributions and individual points lower right.'},
 {n:'02',short:'Selective loss',title:'Whose evidence survives?',path:'paper-concepts/02-selective-loss',data:'paper-concepts/02-selective-loss.csv',question:'Are minority objections, uncertainty and conditions disproportionately lost?',read:'Soft distributions show retention across cases; faint dots reveal variation. The lower panel holds evidence constant and changes a contributor’s status label. Zero means no label effect.',experiment:'Annotate information types within each consultation. Separately run matched swaps of prestige labels, order and verbosity while holding meaning fixed. Compare within-case changes rather than treating category differences alone as bias.',limit:'120 hypothetical cases per category plus 120 simulated label-swap pairs. Density is descriptive; bold marks show medians and interquartile ranges, not confidence intervals.',alt:'Simulated retention rainclouds for majority findings, minority objections, uncertainty and conditions, with a separate matched prestige-label effect distribution.'},
 {n:'03',short:'Summary accuracy',title:'Does the summary change the evidence?',path:'paper-concepts/03-summary-accuracy',data:'paper-concepts/03-summary-accuracy.csv',question:'Does the final summary accurately describe recorded agreement?',read:'The diagonal means exact reporting. Points above it overstate agreement; points below understate it. The adjacent distributions reveal whether errors concentrate in unresolved claims or minority warnings.',experiment:'Compare numerical claims in summaries with the saved rating table, using a fixed denominator. Audit missingness, qualifications and attribution separately; counts alone do not establish semantic fidelity.',limit:'240 simulated rated claims. The 50% and 90% contours describe the constructed density, not statistical uncertainty or observed platform behaviour.',alt:'Illustrative recorded versus reported agreement density map with a perfect-reporting diagonal and signed-error distributions for three claim types.'},
 {n:'04',short:'Deliberation',title:'Agreement is not the same as accuracy',path:'paper-concepts/04-deliberation',data:'paper-concepts/04-deliberation.csv',question:'Does feedback improve understanding, or merely make people agree?',read:'Faint lines follow panels from the first rating round to the second; bold lines show means. The map separates convergence with improving factual accuracy from convergence with worsening accuracy.',experiment:'Compare feedback with a no-feedback control while keeping claims and scales fixed. Use a prespecified disagreement measure and assess factual accuracy only where answers are known. Keep policy preferences separate.',limit:'100 hypothetical paired panels per condition. Both scores and changes are constructed. These plots demonstrate an analysis design; they do not establish feedback effects.',alt:'Simulated round-two to round-three disagreement trajectories with and without feedback, beside a map of disagreement change versus factual-accuracy change.'},
 {n:'04b',short:'Deliberation · overview',wide:true,title:'From round-two ratings to round-three judgments',path:'paper-concepts/deliberation-overview',data:'paper-concepts/04-deliberation.csv',question:'Does feedback change the distribution of views, reduce disagreement, and improve factual judgment?',read:'Panel a compares discrete rating proportions in three separate hypothetical examples: persistent disagreement, convergence and growing polarisation. Panel b follows 100 simulated consultations in each arm; below the diagonal means less disagreement. Panel c uses the same feedback cases to distinguish convergence with improving accuracy from convergence with worsening accuracy.',experiment:'Randomise consultations to feedback or repeat rating without feedback. Keep claims and scales fixed, prespecify disagreement, compare matched participants, and report attrition. Assess accuracy only on objectively assessable tasks; assess understanding separately for preferences.',limit:'Entirely illustrative. Panel a uses separately constructed rating counts, not examples drawn from b–c. Panels b–c reuse existing simulated scores, which were not calculated from recorded ballots. Contours describe density, not confidence intervals. No new model calls or participant experiments were run. Original figure views remain available.',alt:'Combined round-two to round-three design: three discrete rating-distribution examples above two square disagreement maps for no feedback and peer feedback, beside an accuracy-change map, with full explanatory caption.'},
 {n:'05',short:'Decisions',title:'Does information loss change decisions?',path:'paper-concepts/05-decision-consequences',data:'paper-concepts/05-decision-consequences.csv',question:'Do readers make worse decisions when the evidence is compressed?',read:'Compare decision-loss distributions for the full record, an ordinary summary and a proposed traceable summary. Paired case differences show the comparison directly; calibration separates confidence from correctness.',experiment:'Randomize blinded readers to evidence presentations. Define decision loss before collecting outcomes, assess comprehension and confidence, and account for both readers and cases. A traceable summary is a proposed comparator, not an established improvement.',limit:'120 simulated case-level loss triples; calibration curves are separately constructed. Apparent benefits are chosen for the illustration, not measured or predicted.',alt:'Illustrative reader decision-loss distributions across three evidence presentations, paired case differences and confidence calibration curves.'},
 {n:'06',short:'Disagreement',title:'Does summarisation manufacture consensus?',path:'paper-concepts/06-preserving-disagreement',data:'paper-concepts/06-preserving-disagreement.csv',question:'Can a shorter summary preserve the shape of disagreement, rather than inventing a shared middle?',read:'Read down the three waves. The original views have two peaks. The amber reconstruction collapses them toward neutrality; the last reconstruction preserves both peaks. Dashed outlines retain the original reference, while faint ticks show individual positions. All rows use identical scales and deliberately share the same mean.',experiment:'Record experts’ original positions, then ask blinded readers to reconstruct how those experts were distributed after reading different summaries. Compare the reconstructed distributions with the original, at matched word budgets. Measure artificial centralization and lost modes as well as average position. Separately annotate whether reasons and conditions survive; distribution fidelity alone cannot establish semantic fidelity.',limit:'Illustrative only: 240 constructed positions in each row. Equal means are imposed by mirrored samples, not discovered experimentally. Rows 2–3 represent hypothetical reader reconstructions of experts’ positions—not readers’ own beliefs or distributions automatically extracted from prose. This is one two-camp example; real disagreement need not be bimodal. No readers or models were tested.',alt:'Three illustrative waves with equal means: original opposing peaks in purple and teal; an amber central hump showing artificial consensus; and two preserved peaks overlaid on dashed original outlines.'}
 ];
 const $=id=>document.getElementById(id),el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};
 const buttons=figures.map((f,i)=>{const b=el('button');b.type='button';b.append(el('span',f.n),el('strong',f.short));b.onclick=()=>render(i);return b});
 function render(i){const f=figures[i];buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));
 $('concept-kind').textContent=f.wide?'ROUND 2 → ROUND 3 · ILLUSTRATIVE DESIGN':(f.companion||f.composition)?'ROUND 1 → ROUND 2 · ILLUSTRATIVE MAP + SAVED PILOT + ILLUSTRATIVE TYPES':f.measured?'SAVED ASSISTANT PILOT · PROVISIONAL SELF-REVIEW':'ILLUSTRATIVE FIGURE';
 $('concept-title').textContent=f.title;$('concept-question').textContent=f.question;
 $('concept-companion').hidden=!f.companion; $('concept-retention').hidden=!f.companion; $('concept-image').closest('article').classList.toggle('concept-pair',!!f.companion); $('concept-image').closest('article').classList.toggle('concept-composition',!!(f.composition||f.wide));
 const img=$('concept-image');img.src=f.path+'.svg'+(f.composition?'?v=grouping-polished-1':f.measured?'?v=meaning-scenarios-1':f.n==='06'?'?v=waves-2':'');img.alt=f.alt;$('concept-full').href=f.path+'.svg'+(f.composition?'?v=grouping-polished-1':f.measured?'?v=meaning-scenarios-1':f.n==='06'?'?v=waves-2':'');
 $('concept-read').textContent=f.read;$('concept-experiment').textContent=f.experiment;$('concept-limit').textContent=f.limit;
 $('concept-downloads').replaceChildren(...[['SVG',f.path+'.svg'],['Vector PDF',f.path+'.pdf'],['600 dpi PNG',f.path+'.png'],[f.measured?'Panel scores CSV':'Simulated data CSV',f.data]].map(([label,url])=>{const a=el('a',label);a.href=url+(f.composition?'?v=grouping-polished-1':f.measured?'?v=meaning-scenarios-1':f.n==='06'?'?v=waves-2':'');return a}));
 if(f.wide){for(const [label,url] of [['Rating examples CSV','paper-concepts/deliberation-rating-examples.csv'],['Design provenance','paper-concepts/deliberation-overview-provenance.json']]){const a=el('a',label);a.href=url;$('concept-downloads').append(a)}}
 if(f.composition){const a=el('a','Simulation design / provenance');a.href='paper-concepts/grouping-design.json';$('concept-downloads').append(a)}
 if(f.companion||f.composition){for(const [label,url] of [['Retention SVG','assistant-extraction/retention-summary.svg'],['Retention PDF','assistant-extraction/retention-summary.pdf'],['Retention source counts','assistant-extraction/retention-summary.json'],['Companion SVG','paper-concepts/extraction-companion.svg'],['Companion PDF','paper-concepts/extraction-companion.pdf'],['Companion PNG','paper-concepts/extraction-companion.png'],['Companion simulated data','paper-concepts/02-selective-loss.csv']]){const a=el('a',label);a.href=url;$('concept-downloads').append(a)}}
 }
 $('concept-picker').replaceChildren(...buttons);render(6);
})();
